import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type AnchorHTMLAttributes,
  type MouseEvent,
  type ReactNode,
} from "react";

type RouterValue = {
  path: string;
  navigate: (to: string) => void;
};

const RouterContext = createContext<RouterValue>({ path: "/", navigate: () => {} });

/** Collapse redundant trailing slashes so "/about/" and "/about" resolve identically. */
function normalize(path: string) {
  if (!path) return "/";
  if (path.length > 1 && path.endsWith("/")) return path.slice(0, -1);
  return path;
}

/** Split an href into its pathname and hash so in-page anchors are preserved. */
function splitHref(href: string) {
  const hashAt = href.indexOf("#");
  if (hashAt === -1) return { pathname: href, hash: "" };
  return { pathname: href.slice(0, hashAt), hash: href.slice(hashAt) };
}

export function RouterProvider({ children }: { children: ReactNode }) {
  const [path, setPath] = useState(() => normalize(window.location.pathname));

  useEffect(() => {
    const onPop = () => setPath(normalize(window.location.pathname));
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);

  const navigate = useCallback((to: string) => {
    const { pathname, hash } = splitHref(to);
    const target = normalize(pathname || window.location.pathname);

    if (target === normalize(window.location.pathname) && hash) {
      // Same document: just jump to the requested section.
      document.getElementById(hash.slice(1))?.scrollIntoView({ behavior: "smooth" });
      return;
    }
    if (target === normalize(window.location.pathname)) return;

    window.history.pushState({}, "", target + hash);
    setPath(target);
    if (hash) {
      window.requestAnimationFrame(() => {
        document.getElementById(hash.slice(1))?.scrollIntoView({ behavior: "smooth" });
      });
    } else {
      window.scrollTo(0, 0);
    }
  }, []);

  const value = useMemo(() => ({ path, navigate }), [path, navigate]);
  return <RouterContext.Provider value={value}>{children}</RouterContext.Provider>;
}

export function useRouter() {
  return useContext(RouterContext);
}

/** Returns true for hrefs the browser should handle on its own (mail, phone, pure anchors). */
function isBrowserHandled(href: string) {
  return (
    href.startsWith("#") ||
    href.startsWith("tel:") ||
    href.startsWith("mailto:") ||
    href.startsWith("javascript:")
  );
}

type LinkProps = AnchorHTMLAttributes<HTMLAnchorElement> & {
  /** Destination path such as "/about/" or "/schools-colleges/". */
  to: string;
};

/**
 * Client-side anchor. Root-relative destinations route through the in-app
 * router; protocol links and bare anchors fall through to the browser.
 */
export function Link({ to, children, onClick, ...rest }: LinkProps) {
  const { navigate } = useRouter();

  if (isBrowserHandled(to)) {
    return (
      <a href={to} {...rest} onClick={onClick}>
        {children}
      </a>
    );
  }

  const internal = to.startsWith("/");
  const href = internal ? to : "#";

  const handleClick = (event: MouseEvent<HTMLAnchorElement>) => {
    onClick?.(event);
    if (!internal) {
      event.preventDefault();
      return;
    }
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || event.button !== 0) {
      return;
    }
    event.preventDefault();
    navigate(to);
  };

  return (
    <a href={href} {...rest} onClick={handleClick}>
      {children}
    </a>
  );
}

